using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.ReadNotes),
};

// --- Agent setup -------------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    tools: tools,
    instructions: """
        You are a research assistant. When the user gives you a topic:
        1. Search the web multiple times with different queries to gather broad information.
        2. Save the most important findings as notes using the note-taking tool.
        3. After gathering enough information, read all your notes and produce a
           well-structured summary with key facts, organized by subtopic.
        Always cite which search results informed each point.
        """);

// --- Run the agent -----------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching \"{topic}\"...\n");

var session = await agent.CreateSessionAsync();

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

await foreach (var update in agent.RunStreamingAsync(topic, session, runOptions))
{
    foreach (var message in update.Messages)
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }
}

Console.WriteLine();

// --- Tool implementations ----------------------------------------------------

[Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
static string SearchWeb(
    [Description("The search query string")] string query)
{
    // Simulated web search results keyed on common research terms.
    // In production, replace with a real search API (Bing, Google, etc.).
    var results = new StringBuilder();
    results.AppendLine($"Search results for: \"{query}\"\n");

    var lowerQuery = query.ToLowerInvariant();

    if (lowerQuery.Contains("quantum computing"))
    {
        results.AppendLine("""
            1. "What Is Quantum Computing?" — IBM Research (ibm.com/quantum)
               Snippet: Quantum computing uses qubits that leverage superposition and entanglement
               to perform calculations exponentially faster than classical computers for certain problems.

            2. "Quantum Advantage Demonstrated" — Nature (nature.com/articles/s41586-024-07998)
               Snippet: Google's Willow chip (2024) solved a benchmark problem in under 5 minutes
               that would take a classical supercomputer 10 septillion years.

            3. "Quantum Error Correction Breakthrough" — MIT Technology Review (technologyreview.com)
               Snippet: Researchers achieved below-threshold error rates using surface codes,
               a critical milestone toward fault-tolerant quantum computing.

            4. "Applications of Quantum Computing" — McKinsey & Company (mckinsey.com)
               Snippet: Key application areas include cryptography, drug discovery, materials science,
               financial modeling, and optimization problems in logistics.

            5. "Quantum Programming Languages" — Microsoft Research (microsoft.com/research)
               Snippet: Q# and Qiskit are leading quantum programming frameworks. Azure Quantum
               provides cloud access to quantum hardware from IonQ, Quantinuum, and others.
            """);
    }
    else if (lowerQuery.Contains("artificial intelligence") || lowerQuery.Contains(" ai ") || lowerQuery.StartsWith("ai "))
    {
        results.AppendLine("""
            1. "State of AI Report 2025" — Stanford HAI (hai.stanford.edu)
               Snippet: Global AI investment exceeded $200B in 2024. Foundation models now power
               applications across healthcare, law, education, and scientific research.

            2. "AI Safety and Alignment" — Anthropic Research (anthropic.com/research)
               Snippet: Constitutional AI and RLHF techniques help align large language models
               with human values, reducing harmful outputs by over 80%.

            3. "Generative AI in Enterprise" — Gartner (gartner.com)
               Snippet: By 2026, over 80% of enterprises will have deployed generative AI
               in production, up from less than 5% in 2023.
            """);
    }
    else if (lowerQuery.Contains("climate") || lowerQuery.Contains("renewable") || lowerQuery.Contains("energy"))
    {
        results.AppendLine("""
            1. "Renewable Energy Growth 2025" — IEA (iea.org)
               Snippet: Renewable capacity additions hit 650 GW in 2024, led by solar PV.
               Renewables now generate over 35% of global electricity.

            2. "Climate Change Impacts" — IPCC Sixth Assessment (ipcc.ch)
               Snippet: Global temperatures have risen 1.2°C above pre-industrial levels.
               Limiting warming to 1.5°C requires halving emissions by 2030.

            3. "Carbon Capture Technologies" — DOE (energy.gov)
               Snippet: Direct air capture costs have fallen to $250-$400 per ton of CO2.
               The US has funded 4 major DAC hubs targeting 1M tons/year each.
            """);
    }
    else
    {
        results.AppendLine($"""
            1. "Overview of {query}" — Wikipedia (en.wikipedia.org)
               Snippet: {query} is a broad topic with applications across multiple domains.
               Recent developments have accelerated interest from both industry and academia.

            2. "Latest Research on {query}" — arXiv (arxiv.org)
               Snippet: Multiple papers published in 2024-2025 explore new approaches to {query},
               including novel algorithms, frameworks, and real-world applications.

            3. "{query}: Industry Outlook" — Forbes (forbes.com)
               Snippet: Market analysts project significant growth in {query}-related sectors,
               driven by technological advances and increasing demand.

            4. "Understanding {query}" — MIT OpenCourseWare (ocw.mit.edu)
               Snippet: Free educational resources covering fundamentals and advanced concepts
               of {query}, including lecture notes, assignments, and video lectures.
            """);
    }

    return results.ToString();
}

// --- Notebook helper ---------------------------------------------------------

sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important findings from search results.")]
    public string SaveNote(
        [Description("Title or label for the note")] string title,
        [Description("Content of the note with key facts")] string content)
    {
        _notes.Add($"## {title}\n{content}");
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Read all saved research notes. Use this to review findings before writing a summary.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== {_notes.Count} Research Notes ===\n");
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"Note {i + 1}:");
            sb.AppendLine(_notes[i]);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

