 using System.ComponentModel;
 using System.Text;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration -----------------------------------------------------------

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Tools -------------------------------------------------------------------

 var notebook = new Notebook();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(SearchWeb),
     AIFunctionFactory.Create(notebook.SaveNote),
     AIFunctionFactory.Create(notebook.ReadNotes),
 };

 // --- Agent setup -------------------------------------------------------------

 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 var agent = new ChatClientAgent(
     chatClient,
     tools: tools,
     instructions: """
         You are a research assistant. When the user gives you a topic:
         1. Search the web multiple times with different queries to gather broad information.
         2. Save the most important findings as notes using the note-taking tool.
         3. After gathering enough information, read all your notes and produce a
            well-structured summary with key facts, organized by subtopic.
         Always cite which search results informed each point.
         """);

 // --- Run the agent -----------------------------------------------------------

 Console.WriteLine("=== Research Agent ===");
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine()?.Trim();

 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching \"{topic}\"...\n");

 var session = await agent.CreateSessionAsync();

 var runOptions = new ChatClientAgentRunOptions
 {
     ChatOptions = new ChatOptions
     {
         Temperature = 0f,
         MaxOutputTokens = 2048,
     },
 };

 await foreach (var update in agent.RunStreamingAsync(topic, session, runOptions))
 {
     if (update.Role == ChatRole.Assistant && !string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine();

